export const REQUEST_FIELDS = { unitId: "unitId", coverageRequirement: "coverageRequirement" } as const;
export const REQUIRED_COVERAGE = "required";

export function createValidRequest(): Readonly<Record<string, string>> {
  return { [REQUEST_FIELDS.unitId]: crypto.randomUUID(), [REQUEST_FIELDS.coverageRequirement]: REQUIRED_COVERAGE };
}

export async function submitRequest(request: Readonly<Record<string, string>>): Promise<{ accepted: boolean }> {
  return { accepted: Boolean(request[REQUEST_FIELDS.unitId]) && request[REQUEST_FIELDS.coverageRequirement] === REQUIRED_COVERAGE };
}

